<?php
namespace App\Modules\Counselor\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Counselor\{Services\CounselorService,Models\Counselor,Resources\CounselorResource,Requests\StoreCounselorRequest,Requests\UpdateCounselorRequest,Requests\IndexCounselorRequest};use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;
class CounselorController extends Controller {public function __construct(private CounselorService $service){}public function index(IndexCounselorRequest $r){$f=$r->validated();if(!$r->user()?->hasAdminPermission('counselors.manage')){$f['active']=true;$f['public']=true;}return CounselorResource::collection($this->service->index($f));}public function show(string $counselor){$admin=request()->user()?->hasAdminPermission('counselors.manage')??false;$query=Counselor::query()->where('slug',$counselor);if($admin)$query->with('specialties');else $query->with(['specialties'=>fn($q)=>$q->where('is_active',true)]);$c=$query->firstOrFail();abort_unless($admin||($c->is_active&&$c->is_public),404);return new CounselorResource($c);}public function store(StoreCounselorRequest $r){$c=$this->service->create($r->validated());$this->audit($r,'counselor.profile_created',$c->id,['is_active'=>$c->is_active,'is_public'=>$c->is_public]);return (new CounselorResource($c))->response()->setStatusCode(201);}public function update(UpdateCounselorRequest $r,int $counselor){$c=$this->service->find($counselor)??abort(404);$fields=array_keys($r->validated());$c=$this->service->update($c,$r->validated());$this->audit($r,'counselor.profile_updated',$c->id,['fields'=>$fields]);return new CounselorResource($c);}public function destroy(int $counselor){$c=$this->service->find($counselor)??abort(404);Gate::authorize('delete',$c);$this->service->delete($c);$this->audit(request(),'counselor.profile_deleted',$c->id,[]);return response()->noContent();}private function audit(Request $r,string $action,int $id,array $details):void{\Illuminate\Support\Facades\DB::table('booking_audit_events')->insert(['actor_id'=>$r->user()->id,'action'=>$action,'details'=>json_encode(['counselor_id'=>$id,...$details]),'created_at'=>now(),'updated_at'=>now()]);}}
